"""The generated page of tools/bench/failure_attribution.py (analysis only; see that file for what is read and what is not changed)."""
from __future__ import annotations

import collections

CHANGE_OF = {
    "critical-mass cap": "the head's critical-mass cap (0.05) now applies to every model candidate; the earlier evaluator had no cap, no head and no window",
    "head probability below the engine threshold": "the candidate is offered with the HEAD's probability as confidence and the engine's per-act threshold now applies; the earlier evaluator had no head and no threshold",
    "critical-cue or critical-act menu (shipped, before the model)": "the shipped Interpreter runs first and sends a sentence whose head top act is critical (or that matches a cue) to the menu before the model is asked; the earlier evaluator applied only the cue regexes",
    "behaviour window / eligibility of the candidate act": "the candidate must be eligible in the running behaviour window; the earlier evaluator had no window",
    "schema/timeout of the model reply (fell back to the shipped refusal: CRITICAL_MASS)": "strict reader and fallback: the live reply was lost (timeout) so the shipped decision stood, and the shipped path refuses these rows at the cap",
}


def page(rows: list, variants: dict, checks: dict, ctab: dict) -> str:
    L = []
    w = L.append
    A = {r["id"] for r in rows if r["A_guarded"]["ok"]}
    B = {r["id"] for r in rows if r["B_current"]["ok"]}
    S = {r["id"] for r in rows if r["S_shipped"]["ok"]}
    Araw = {r["id"] for r in rows if r["A_raw"]["ok"]}
    w("# Failure attribution of the semantic reader on the 140 legitimate dev rows (generated, analysis only)\n")
    w("> Generated by `tools/bench/failure_attribution.py --report` from recorded replies and cached embeddings; **no cloud call, no guard, threshold or flag changed, no frozen-set content read.** Synthetic builder-written labels; the dev split is where the baseline and prompts were developed; this page says WHERE rows are lost, not how the system generalises. "
      "Proposal and decision request: `docs/research/semantic_reader_architecture_proposal.md`.\n")
    w("## 1. The discrepancy, reconciled\n")
    w("| system | legitimate rows credited under the right act (of 140) | what it is |")
    w("|---|---|---|")
    w(f"| raw Gemma, strict replies, no guards | {len(Araw)} | the model's SUPPORTED finding, credit rule only |")
    w(f"| **A: earlier guarded evaluator** (strict replies, critical-cue and assertion guards) | **{len(A)}** | `rubric_compare` rule: no head, no cap, no window, no threshold, no status or waiting-state rule |")
    w(f"| S: shipped path (no model) | {len(S)} | gate, cap 0.05, engine thresholds, validation |")
    w(f"| **B: current pipeline** (live Gemma replies replayed, strict reader) | **{len(B)}** | shipped checks first, then the reader's candidate behind validation, the cap and the threshold; the replay reproduces the live run's 92/140 |")
    w(f"\nThe 26-row gap is a NET figure. Row by row: credited by A and B {len(A & B)}; **credited by A but lost by B: {len(A - B)}**; credited by B but not A: {len(B - A)}; {len(A - B)} - {len(B - A)} = {len(A - B) - len(B - A)}. "
      "B also differs from A in the prompt (the live reader's format instruction and context), so a row can change because the model's reading changed; section 3 separates that.\n")
    w("## 2. Where every legitimate row is lost\n")
    for key, name in (("B_current", "B current pipeline"), ("S_shipped", "S shipped path"), ("A_guarded", "A earlier guarded evaluator")):
        if key == "A_guarded":
            c = collections.Counter(("model credited another act or several" if r["A_guarded"]["decision"] else ("reply unusable (malformed)" if not r["A_guarded"]["valid"] else "model did not credit (not supported, uncertain or guard)")) for r in rows if not r["A_guarded"]["ok"])
        else:
            c = collections.Counter(r[key]["cause"] for r in rows if not r[key]["ok"])
        w(f"**{name}: {sum(c.values())} rows lost**\n")
        w("| first blocking component | rows |")
        w("|---|---|")
        for k, v in c.most_common():
            w(f"| {k} | {v} |")
        w("")
    w("## 3. Differential analysis: the rows credited by A and lost by B\n")
    lost = [r for r in rows if r["id"] in A - B]
    c = collections.Counter(r["B_current"]["cause"] for r in lost)
    w("| cause in B | rows | architectural change that caused it |")
    w("|---|---|---|")
    for k, v in c.most_common():
        w(f"| {k} | {v} | {CHANGE_OF.get(k, k)} |")
    right = sum(1 for r in lost if r["B_current"]["live_reading"] and any(f["objective"] == r["act"] and f["verdict"] == "SUPPORTED" for f in r["B_current"]["live_reading"].get("findings", [])))
    w(f"\nOf these {len(lost)} rows, the live reading supported the row's own act in {right}: the model's semantic decision was right and a later component refused it.\n")
    w("| id | text | head mass (cap 0.05) | p(row act) | engine threshold | head top act | cause |")
    w("|---|---|---|---|---|---|---|")
    for r in sorted(lost, key=lambda r: r["id"]):
        h = r["head"]
        w(f"| {r['id']} | {r['text'][:60]} | {h['critical_mass']} | {h['p_row_act']} | {h['engine_threshold_row_act']} | {h['top_act']} | {r['B_current']['cause'][:60]} |")
    gained = [r for r in rows if r["id"] in B - A]
    w(f"\n**Credited by B but not by A ({len(gained)}):** " + "; ".join(f"{r['id']} \"{r['text'][:40]}\" (A: {r['A_guarded']['decision'] or 'no credit'})" for r in gained) +
      ". The ANSWER_QUESTION rows are credited by B because the benchmark gives that act its waiting patient question and the head knows the act; A had the model name EXPLAIN_PROCEDURE.\n")
    capped = [r for r in rows if r["head"]["over_cap"] and not r["B_current"]["ok"]]
    w(f"**The cap in numbers.** {len(capped)} legitimate dev rows have a critical mass of 0.05 or more and are not credited by B; for {sum(1 for r in capped if r['head']['top_act'] == r['act'])} of them the head's top act IS the row's act and for "
      f"{sum(1 for r in capped if r['head']['p_row_act'] > r['head']['critical_mass'])} the act's probability is higher than the whole critical mass. Top critical class of the mass: " +
      ", ".join(f"{k} {v}" for k, v in collections.Counter(r['head']['top_critical_class'] for r in capped).most_common()) + ". No critical cue matched any of them.\n")
    w("## 4. False credits of the earlier experiments, and which independent check refuses them\n")
    w(f"Raw Gemma replies (strict or fenced view, any split) credited **{checks['unsafe_rows_credited_by_raw_replies']} unique non-legitimate rows** on dev, test and test2. The earlier guards (assertion layer and cue) removed all but **{checks['survive_the_earlier_guards']}**. "
      "Each check below is one the pipeline already computes; the last column is the cost: legitimate rows credited under the right act by the raw or the guarded replies that the check alone would block.\n")
    w("| check | refuses the raw false credits | refuses the guarded survivors | blocks legitimate rows (of {}) |".format(checks["legit_rows_counted"]))
    w("|---|---|---|---|")
    for n, v in checks["checks"].items():
        w(f"| {n} | {v['rejects_raw_false_credits']}/{checks['unsafe_rows_credited_by_raw_replies']} | {v['rejects_guarded_survivors']}/{checks['survive_the_earlier_guards']} | {v['blocks_legitimate_rows_credited_by_the_guarded_evaluator']} |")
    w("\nThe legitimate-row count is unique rows over the strict and fenced views of all three splits (raw or guarded credit), so it exceeds 140. The guarded survivors (all on test2):\n")
    w("| id | category | text | credited as | p(act) | critical mass | top critical class | model reported a critical objective |")
    w("|---|---|---|---|---|---|---|---|")
    for s in checks["survivors"]:
        w(f"| {s['id']} | {s['category']} | {s['text'][:60]} | {s['credited_act']} | {s['p_act']} | {s['critical_mass']} | {s['top_critical_class']} | {s['model_reported_a_critical_objective']} |")
    w("\n**The current pipeline's one wrong offer (92/93)** is `AB-d0098` \"We start by placing a small line in your arm.\": labelled EXPLAIN_PROCEDURE by construction, credited as EXPLAIN_ACTION by the shipped head (0.85) AND by the model. It is a legitimate sentence under a contested act "
      "(the approved definitions of EXPLAIN_ACTION, \"says what is about to be done to the patient before doing it\", and EXPLAIN_PROCEDURE overlap), not an unsafe credit. No independent evidence should reject it; an independent human label (EX-01) decides which act it is.\n")
    w("## 5. The model's own critical-content reading is an independent signal\n")
    parts = []
    for s, v in ctab.items():
        parts.append(f"{s}: {v['critical_with_a_critical_objective_reported']}/{v['critical_rows']} critical rows but only {v['legitimate_with_a_critical_objective_reported']}/{v['legitimate_rows']} legitimate rows")
    w("Among the objectives the model reports (at most two per reply, fenced view so that no reply is lost), a critical objective appears for " + "; ".join(parts) + ". The misses are the cases where the model read critical content as an ordinary act (the test2 allergy question): exactly the survivors above. "
      "A reading that finds NO critical objective is therefore not evidence that the content is not critical, but one that finds one is strong evidence that it is.\n")
    w("## 6. Counterfactual: the cap corroborated by the model's reading (analysis only, nothing implemented)\n")
    w("The pipeline is replayed with a wrapper that reports the critical mass as passed when the variant's condition holds, using the model's own recorded reading. Everything else is as shipped (cap otherwise, thresholds, window, status checks, cue menu, engine store). "
      "V1: the reading is valid, names exactly one non-critical objective and reports no critical objective at all. V2: V1 and the head's probability for that objective is at least the whole critical mass. V3: V2 and the head's top act is that objective.\n")
    w("| replies replayed | variant | legitimate recall (of 140) | credited precision | critical false credit (of 40) | adversarial false credit (of 300) |")
    w("|---|---|---|---|---|---|")
    for k, d in variants.items():
        for v, x in d.items():
            w(f"| {k.replace('_', ' ')} | {v} | {x['legit_recall']} | {x['credited_precision']} | {x['critical_false_credit']} | {x['adversarial_false_credit']} |")
    w("\nShipped path alone: dev 95/140, test 76/140, test2 79/140. The only unsafe offer in any of these rows is V1's food question on test2 (a recognition-error copy of the allergy question), which V2's dominance condition removes. "
      "The wrong offers on dev are the contested EXPLAIN_ACTION sentence of section 4 and its recognition-error copy.\n")
    w("## 7. What this does and does not show\n")
    w("The variant results use the model's recorded readings of the benchmark sentences and the head's signals for them; the conditions were read off the analysis of dev, test and test2 and were not tuned on a held-out set, so they are exploratory. "
      "The 8 sentences that leak when the cap is removed from the safety panel (`reports/ai/recall-safety-panel.json`: fasting, blood thinner, \"initial each box\", senior anaesthetist...) all have the ordinary act outweighing the critical mass (ratio 1.9 to 10), so the dominance condition does not stop them: "
      "only the model's critical reading could, and the model was never asked about them (it needs a small live run). Zero observed unsafe offers on synthetic rows is not a safety guarantee.\n")
    return "\n".join(L) + "\n"
